package com.jayaseelan.nexoramart.service;
import com.jayaseelan.nexoramart.dao.ProductDAO; import com.jayaseelan.nexoramart.model.Product; import java.math.BigDecimal; import java.util.List;
public class ProductService{private final ProductDAO dao;public ProductService(ProductDAO d){dao=d;}private void valid(Product p){if(p.getName()==null||p.getName().isBlank())throw new IllegalArgumentException("Product name is required.");if(p.getCategory()==null||p.getCategory().isBlank())throw new IllegalArgumentException("Category is required.");if(p.getPrice()==null||p.getPrice().compareTo(BigDecimal.ZERO)<=0)throw new IllegalArgumentException("Price must be greater than 0.");if(p.getStockQty()<0)throw new IllegalArgumentException("Stock cannot be negative.");}public void create(Product p)throws Exception{valid(p);dao.create(p);}public List<Product> browse(String q,String c)throws Exception{return dao.findAll(q,c);}public List<Product> seller(long id)throws Exception{return dao.findBySeller(id);}public Product byId(long id)throws Exception{return dao.findById(id);}public void update(Product p,long id)throws Exception{valid(p);dao.update(p,id);}public void delete(long id,long sid)throws Exception{dao.delete(id,sid);}}
